import{_ as e,o as l,c as i,a8 as o}from"./chunks/framework.BppdKxCY.js";const u=JSON.parse('{"title":"EP.63 RAG 让 AI 不再胡说","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.63-rag-knowledge-base.md","filePath":"comics/EP.63-rag-knowledge-base.md","lastUpdated":1793706365000}'),t={name:"comics/EP.63-rag-knowledge-base.md"};function r(n,a,s,d,h,c){return l(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="ep-63-rag-让-ai-不再胡说" tabindex="-1">EP.63 RAG 让 AI 不再胡说 <a class="header-anchor" href="#ep-63-rag-让-ai-不再胡说" aria-label="Permalink to &quot;EP.63 RAG 让 AI 不再胡说&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../89-rag-knowledge-base">89-rag-knowledge-base.md</a>（89.1 RAG 原理 / 89.2 文档分块与 embedding / 89.3 对话记忆）· 示例：<code>examples/89-01-rag-knowledge-base.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：用户问产品营收，AI 凭空编数——大模型幻觉。</li><li><strong>第 2 格</strong>：码叔揭秘 RAG——先检索私有文档，再把上下文喂给 LLM 生成。</li><li><strong>第 3 格</strong>：像素酱实证分块与 embedding——文档切块转向量，余弦相似度取 Top-K。</li><li><strong>第 4 格</strong>：码叔结案——多轮对话用滑动窗口+摘要管理上下文长度。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-幻觉的根源" tabindex="-1">第 1 格 · 幻觉的根源 <a class="header-anchor" href="#第-1-格-·-幻觉的根源" aria-label="Permalink to &quot;第 1 格 · 幻觉的根源&quot;">​</a></h3><ul><li>LLM 训练数据有截止日期，不知道最新/私有信息；</li><li>没有事实依据时会&quot;一本正经地胡说&quot;；</li><li>解决思路：给模型提供可参考的上下文。</li></ul><h3 id="第-2-格-·-rag-流程" tabindex="-1">第 2 格 · RAG 流程 <a class="header-anchor" href="#第-2-格-·-rag-流程" aria-label="Permalink to &quot;第 2 格 · RAG 流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户问题 → 向量化 → 向量库检索 Top-K → 拼装 Prompt → LLM 生成</span></span></code></pre></div><ul><li>RAG = Retrieval-Augmented Generation；</li><li>不微调模型，而是检索知识注入 Prompt；</li><li>模型只负责阅读理解和生成，降低幻觉。</li></ul><h3 id="第-3-格-·-分块与向量检索" tabindex="-1">第 3 格 · 分块与向量检索 <a class="header-anchor" href="#第-3-格-·-分块与向量检索" aria-label="Permalink to &quot;第 3 格 · 分块与向量检索&quot;">​</a></h3><ul><li>文档按 token 切块（如 512 token + 50 重叠），避免语义断裂；</li><li>每块转 embedding 向量存向量数据库（Milvus / Pinecone / pgvector）；</li><li>查询时算余弦相似度，取 Top-K 相关块；</li><li>可加 Rerank（交叉编码器）精排提升精度。</li></ul><h3 id="第-4-格-·-对话记忆管理" tabindex="-1">第 4 格 · 对话记忆管理 <a class="header-anchor" href="#第-4-格-·-对话记忆管理" aria-label="Permalink to &quot;第 4 格 · 对话记忆管理&quot;">​</a></h3><ul><li>滑动窗口：保留最近 N 轮对话；</li><li>摘要压缩：历史对话压缩成一句话；</li><li>向量记忆：用语义检索找相关历史；</li><li>Token 预算要分配给系统提示、检索内容、历史、回答。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../89-rag-knowledge-base#_89-7-本章避坑清单">《89.7 本章避坑清单》</a></p></blockquote><ol><li>分块无重叠 → 语义被切断，检索召回率低；</li><li>Top-K 太少或太多 → 少了漏信息，多了塞爆 Prompt 还引入噪音；</li><li>不做对话窗口管理 → 多轮后 Prompt 超限报错。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>RAG 的核心思想是什么？——<strong>不微调模型，检索私有知识注入 Prompt，让模型基于事实生成</strong>。</li><li>文档分块为什么要加重叠？——<strong>防止一句话被切成两块导致语义断裂，提升检索召回率</strong>。</li><li>多轮对话的上下文管理有哪些策略？——<strong>滑动窗口、摘要压缩、向量记忆，工程上常用窗口+摘要混合</strong>。</li></ol>',19)])])}const p=e(t,[["render",r]]);export{u as __pageData,p as default};
